enum Cmd { Put(Message, oneshot::Sender<()>), Get(oneshot::Sender<Message>) }
let (tx, mut rx) = mpsc::channel::<Cmd>(64);            // activation queue
tokio::spawn(async move {
    let mut servant = MQServant::new();
    while let Some(cmd) = rx.recv().await {             // scheduler task
        match cmd {
            Cmd::Put(m, reply) => { servant.put_i(m); let _ = reply.send(()); }
            Cmd::Get(reply)    => { let _ = reply.send(servant.get_i()); }
        }
    }
});
