enum Cmd { Put(Message, mpsc::Sender<()>), Get(mpsc::Sender<Message>) }
let (tx, rx) = mpsc::sync_channel::<Cmd>(64);          // bounded queue
thread::spawn(move || {
    let mut servant = MQServant::new();
    for cmd in rx {                                    // scheduler loop
        match cmd {
            Cmd::Put(m, reply) => { servant.put_i(m); let _ = reply.send(()); }
            Cmd::Get(reply)    => { let _ = reply.send(servant.get_i()); }
        }
    }
});
